// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(address actor) public {
        // Deploy the admissible adversarial counterparty: a caller contract that
        // presents the expected supportsToken() return, then invokes c.airDrop().
        BankCaller caller = new BankCaller();
        // Drive the whole interaction from a fuzzed actor (wide domain).
        vm.assume(actor != address(caller));
        vm.prank(actor);
        bool ok = caller.trigger(address(c));
        // Universal rule: whenever airDrop is invoked through a counterparty whose
        // supportsToken() matches the expected hash, the call succeeds and credits
        // the counterparty 20 tokens. The mutant compares against a wrong string,
        // so the very same call reverts and the balance stays 0.
        assertTrue(ok && c.tokenBalance(address(caller)) == 20);
    }
}

contract BankCaller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function trigger(address target) external returns (bool) {
        (bool s, ) = target.call(abi.encodeWithSignature("airDrop()"));
        return s;
    }
}
